<script setup lang="ts">
import type {TutorialDetail,ChapterContent,PurchaseState} from '@devstore/shared-types';import {ApiError} from '@devstore/api-client';import MarkdownContent from '@devstore/ui/MarkdownContent.vue';import {money} from '@devstore/ui/format';import {BookOpen,LockKeyhole,ArrowRight} from '@lucide/vue';
const route=useRoute();const api=useApi();const {user}=useSession();const {buy,pending:buying,error:buyError}=usePurchase();
const {data:tutorial,error,status,refresh}=await useAsyncData(()=> 'private:tutorial:'+(user.value?.id||'anonymous')+':'+route.params.slug,()=>api.request<TutorialDetail>('/tutorials/'+encodeURIComponent(String(route.params.slug))));
const {data:access,status:accessStatus}=await useAsyncData(()=> 'private:purchase:'+(user.value?.id||'none')+':'+(tutorial.value?.product_id||String(route.params.slug)),()=>user.value&&tutorial.value?api.request<PurchaseState>('/me/purchases/'+tutorial.value.product_id):Promise.resolve(null),{server:false});
const checkingAccess=computed(()=>!!user.value && accessStatus.value!=='error' && !access.value);
const selected=ref('');const content=ref<ChapterContent|null>(null);const loading=ref(false);const message=ref('');const locked=ref(false);let controller:AbortController|undefined;
async function read(id:string){
 if(!tutorial.value)return;controller?.abort();controller=new AbortController();const signal=controller.signal;
 selected.value=id;content.value=null;message.value='';locked.value=false;loading.value=true;
 try{const value=await api.request<ChapterContent>('/tutorials/'+tutorial.value.id+'/chapters/'+id,{signal});if(!signal.aborted)content.value=value;}
 catch(e){if(signal.aborted)return;if(e instanceof ApiError&&[401,403].includes(e.status))locked.value=true;else message.value=e instanceof Error?e.message:'章节加载失败，请重试';}
 finally{if(!signal.aborted)loading.value=false;}
}
function openChapter(){const initial=String(route.query.chapter||'');const chapters=tutorial.value?.chapters||[];const chapter=chapters.find(c=>c.id===selected.value)||chapters.find(c=>c.id===initial)||chapters.find(c=>c.is_preview)||chapters[0];if(!chapter){selected.value='';return;}void read(chapter.id);}
watch(()=>[user.value?.id||'',tutorial.value?.id||'',String(route.query.chapter||'')],(next,prev)=>{controller?.abort();content.value=null;locked.value=false;if(prev&&next[2]!==prev[2])selected.value='';openChapter();},{immediate:true});
onBeforeUnmount(()=>{controller?.abort();content.value=null;});
useSeoMeta({title:()=>tutorial.value?.title+' · DevStore',description:()=>tutorial.value?.description||'技术教程在线阅读'});
</script>
<template><div class="container"><div class="page-head"><div class="breadcrumbs"><NuxtLink to="/tutorials">教程中心</NuxtLink><span>/ 在线阅读</span></div><h1 v-if="tutorial">{{ tutorial.title }}</h1><p class="muted">{{ tutorial?.description }}</p><ApiFeedback :pending="status==='pending'" :error="error" @retry="refresh"/></div><div v-if="tutorial" class="reader"><aside class="reader-sidebar panel"><div class="spread" style="margin-bottom:15px"><h2 style="margin:0">课程目录</h2><span class="muted" style="font-size:11px">{{ tutorial.chapters.length }} 章</span></div><ul class="chapter-list"><li v-for="chapter in tutorial.chapters" :key="chapter.id"><button :class="{selected:selected===chapter.id}" :aria-current="selected===chapter.id?'page':undefined" @click="read(chapter.id)"><span>{{ chapter.title }}</span><BookOpen v-if="chapter.is_preview" :size="14"/><LockKeyhole v-else :size="14"/></button></li></ul><div class="divider"/><p class="muted" style="font-size:11px">预览章节无需购买；已购内容登录后即可阅读。</p><span v-if="tutorial.is_demo" class="badge amber">示例内容</span></aside><section class="reader-content panel"><ClientOnly><p v-if="loading" class="muted" role="status">正在加载章节…</p><div v-else-if="locked" class="empty"><LockKeyhole :size="30" style="color:#b8afff;margin:0 auto 20px"/><h2 style="font-size:22px;color:var(--ink)">购买后解锁本章节</h2><p>学习完整内容，继续你的项目实践。</p><NuxtLink v-if="access?.open_order_id" class="btn" :to="'/checkout/'+access.open_order_id">继续处理订单 <ArrowRight :size="15"/></NuxtLink><button v-else-if="tutorial.product_status==='published'" class="btn" :disabled="buying || checkingAccess" @click="buy(tutorial.product_id)">{{ buying?'正在下单…':checkingAccess?'正在确认购买状态…':'购买教程 · '+money(tutorial.price_cents) }}<ArrowRight :size="15"/></button><p v-else class="muted">该教程暂时停止新购。</p><p v-if="buyError" role="alert" class="error">{{ buyError }}</p><NuxtLink v-if="!user" :to="{path:'/login',query:{returnTo:route.fullPath}}" class="text-link" style="display:block;margin-top:16px">已购买？登录继续阅读</NuxtLink></div><div v-else-if="message" role="alert" class="error"><p>{{ message }}</p><button class="btn secondary" @click="read(selected)">重试</button></div><MarkdownContent v-else-if="content" :content="content.content_md"/><p v-else class="muted">选择左侧章节开始阅读。</p><template #fallback><p class="muted">正在准备阅读界面…</p></template></ClientOnly></section></div></div></template>
